    "statements": [
        "长方形周长=(9+4)×2=26厘米",
        "长方形面积=9×4=36平方厘米",
        "正方形周长=6×4=24厘米",
        "正方形面积=6×6=36平方厘米",
        "长方形周长比正方形周长多2厘米",
        "两张纸面积相等"
    ]
}
